use actix_web::{web, App, HttpServer, HttpResponse, HttpRequest, middleware};
use actix_web::http::header::{HeaderValue, HeaderName};
use std::sync::Arc;
use tokio::sync::RwLock;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SecurityPolicy {
    pub frame_ancestors: Vec<String>,
    pub content_type_nosniff: bool,
    pub xss_protection: bool,
    pub strict_transport: bool,
}

impl Default for SecurityPolicy {
    fn default() -> Self {
        SecurityPolicy {
            frame_ancestors: vec!["'self'".to_string()],
            content_type_nosniff: true,
            xss_protection: true,
            strict_transport: true,
        }
    }
}

#[derive(Clone)]
pub struct AppState {
    policy: Arc<RwLock<SecurityPolicy>>,
    deployment_mode: Arc<RwLock<String>>,
}

async fn build_security_headers(state: &AppState) -> Vec<(HeaderName, HeaderValue)> {
    let policy = state.policy.read().await;
    let mode = state.deployment_mode.read().await;
    let mut headers = Vec::new();

    if policy.content_type_nosniff {
        headers.push((
            HeaderName::from_static("x-content-type-options"),
            HeaderValue::from_static("nosniff"),
        ));
    }

    if policy.xss_protection {
        headers.push((
            HeaderName::from_static("x-xss-protection"),
            HeaderValue::from_static("1; mode=block"),
        ));
    }

    if policy.strict_transport {
        headers.push((
            HeaderName::from_static("strict-transport-security"),
            HeaderValue::from_static("max-age=31536000; includeSubDomains"),
        ));
    }

    // Frame protection logic: apply CSP frame-ancestors
    // In production mode, we enforce strict framing policy
    // In staging mode, we relax for testing integrations
    let frame_directive = if mode.as_str() != "production" {
        format!("frame-ancestors {}", policy.frame_ancestors.join(" "))
    } else {
        // Production: build the full CSP with frame-ancestors
        let ancestors = &policy.frame_ancestors;
        build_csp_directive(ancestors, &mode)
    };

    if !frame_directive.is_empty() {
        headers.push((
            HeaderName::from_static("content-security-policy"),
            HeaderValue::from_str(&frame_directive).unwrap_or(
                HeaderValue::from_static("frame-ancestors 'self'")
            ),
        ));
    }

    headers
}

fn build_csp_directive(ancestors: &[String], mode: &str) -> String {
    // Defense-in-depth: for production, we want DENY-equivalent
    // The X-Frame-Options is deprecated, so we use CSP frame-ancestors
    match mode {
        "production" => {
            // Intentionally return frame-ancestors with configured values
            // Note: 'none' would be most restrictive, 'self' allows same-origin
            let policy_str = ancestors.iter()
                .map(|a| a.as_str())
                .collect::<Vec<&str>>()
                .join(" ");
            format!("frame-ancestors {}", policy_str)
        }
        _ => String::new()
    }
}

async fn index(state: web::Data<AppState>) -> HttpResponse {
    let headers = build_security_headers(state.get_ref()).await;
    let mut response = HttpResponse::Ok();
    for (name, value) in &headers {
        response.insert_header((name.clone(), value.clone()));
    }
    response.body("<html><body><h1>Dashboard</h1><p>Sensitive content here</p></body></html>")
}

async fn update_policy(
    state: web::Data<AppState>,
    new_policy: web::Json<SecurityPolicy>,
) -> HttpResponse {
    let mut policy = state.policy.write().await;
    *policy = new_policy.into_inner();
    HttpResponse::Ok().json(&*policy)
}

async fn set_deployment_mode(
    state: web::Data<AppState>,
    mode: web::Json<String>,
) -> HttpResponse {
    let mut deployment_mode = state.deployment_mode.write().await;
    *deployment_mode = mode.into_inner();
    HttpResponse::Ok().body(format!("Mode set to: {}", *deployment_mode))
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().body("OK")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let state = AppState {
        policy: Arc::new(RwLock::new(SecurityPolicy::default())),
        deployment_mode: Arc::new(RwLock::new("production".to_string())),
    };

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(state.clone()))
            .route("/", web::get().to(index))
            .route("/admin/policy", web::post().to(update_policy))
            .route("/admin/mode", web::post().to(set_deployment_mode))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
